contract Reputation is Ownable {
    /**
     * @dev Mapping from an address to its reputation score.
     */
    mapping(address => uint256) private _scores;

    /**
     * @dev Emitted when an account's reputation score is increased.
     * @param account The address whose score was increased.
     * @param amount The amount added to the score.
     * @param newScore The new total score of the account.
     */
    event Increased(address indexed account, uint256 amount, uint256 newScore);

    /**
     * @dev Emitted when an account's reputation score is decreased.
     * @param account The address whose score was decreased.
     * @param amount The amount subtracted from the score.
     * @param newScore The new total score of the account.
     */
    event Decreased(address indexed account, uint256 amount, uint256 newScore);

    /**
     * @dev The constructor is intentionally left empty.
     * The `Ownable` constructor is implicitly called, setting the contract deployer as the initial owner.
     */
    constructor() {
        // This space is intentionally left blank.
    }

    /**
     * @dev Returns the reputation score of a given account.
     * @param account The address to query the score for.
     * @return The reputation score of the account.
     */
    function score(address account) public view returns (uint256) {
        return _scores[account];
    }

    /**
     * @dev Increases the reputation score of an account.
     * This operation can only be performed by the contract owner.
     * Emits an {Increased} event.
     *
     * Requirements:
     * - `account` cannot be the zero address.
     * - The caller must be the owner.
     * - The operation will revert on arithmetic overflow due to Solidity ^0.8.0 checks.
     * @param account The address whose score will be increased.
     * @param amount The amount to increase the score by.
     */
    function increase(address account, uint256 amount) public onlyOwner {
        require(account != address(0), "Reputation: cannot update score for the zero address");

        uint256 currentScore = _scores[account];
        // Solidity ^0.8.0 provides built-in overflow protection
        uint256 newScore = currentScore + amount;

        _scores[account] = newScore;

        emit Increased(account, amount, newScore);
    }

    /**
     * @dev Decreases the reputation score of an account.
     * This operation can only be performed by the contract owner.
     * Emits a {Decreased} event.
     *
     * Requirements:
     * - `account` cannot be the zero address.
     * - `amount` must not be greater than the account's current score.
     * - The caller must be the owner.
     * @param account The address whose score will be decreased.
     * @param amount The amount to decrease the score by.
     */
    function decrease(address account, uint256 amount) public onlyOwner {
        require(account != address(0), "Reputation: cannot update score for the zero address");

        uint256 currentScore = _scores[account];
        require(currentScore >= amount, "Reputation: decrease amount exceeds current score");

        // Solidity ^0.8.0 provides built-in underflow protection
        uint256 newScore = currentScore - amount;

        _scores[account] = newScore;

        emit Decreased(account, amount, newScore);
    }
}

